	"apa": "<p class=\"definition\" data-language=\"en\">That</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\"><abbr title=\"Nominative: subject of a verb\">Nom</abbr></td> <td class=\"htt word\" data-word=\"ap\u0101\u0161\" data-language=\"ht\">ap\u0101\u0161</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Dative: location or destination\">Dat</abbr></td> <td class=\"htt word\" data-word=\"ap\u0113dani\" data-language=\"ht\">ap\u0113dani</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Accusative: object of a verb\">Acc</abbr></td> <td class=\"htt word\" data-word=\"ap\u014dn\" data-language=\"ht\">ap\u014dn</td> </tr>\n</table></p>",
	"apiya": "<p class=\"definition\" data-language=\"en\">There, at that place</p>",
	"appezzi": "<p class=\"definition\" data-language=\"en\">Rear, back (adjective); as a compass direction, west (the west wind was \"the back wind\")</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\"><abbr title=\"Nominative: subject of a verb\">Nom</abbr></td> <td class=\"htt word\" data-word=\"appezzi\u0161\" data-language=\"ht\">appezzi\u0161</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Dative: location or destination\">Dat</abbr></td> <td class=\"htt word\" data-word=\"appezzi\" data-language=\"ht\">appezzi</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Accusative: object of a verb\">Acc</abbr></td> <td class=\"htt word\" data-word=\"appezzin\" data-language=\"ht\">appezzin</td> </tr>\n</table></p>",
