	"e\u0161un": "<p class=\"definition\" data-language=\"en\">I was (at a location: dative)</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\">I was</td> <td class=\"htt word\" data-word=\"e\u0161un\" data-language=\"ht\">e\u0161un</td> </tr>\n\t<tr> <td class=\"eng\">it was</td> <td class=\"htt word\" data-word=\"\u0113\u0161ta\" data-language=\"ht\">\u0113\u0161ta</td> </tr>\n\t<tr> <td class=\"eng\">they were</td> <td class=\"htt word\" data-word=\"e\u0161er\" data-language=\"ht\">e\u0161er</td> </tr>\n</table></p>",
	"gurta": "<p class=\"definition\" data-language=\"en\">Citadel, acropolis: the better-defended upper part of a city with all the temples and palaces</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\"><abbr title=\"Nominative: subject of a verb\">Nom</abbr></td> <td class=\"htt word\" data-word=\"gurta\u0161\" data-language=\"ht\">gurta\u0161</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Dative: location or destination\">Dat</abbr></td> <td class=\"htt word\" data-word=\"gurti\" data-language=\"ht\">gurti</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Accusative: object of a verb\">Acc</abbr></td> <td class=\"htt word\" data-word=\"gurtan\" data-language=\"ht\">gurtan</td> </tr>\n</table></p>",
