	"iyatti": "<p class=\"definition\" data-language=\"en\">\"Iyatti\", a special type of bread \"studded\" with pieces of fruit and cheese</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\"><abbr title=\"Nominative: subject of a verb\">Nom</abbr></td> <td class=\"htt word\" data-word=\"iyatti\u0161\" data-language=\"ht\">iyatti\u0161</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Dative: location or destination\">Dat</abbr></td> <td class=\"htt word\" data-word=\"iyattiya\" data-language=\"ht\">iyattiya</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Accusative: object of a verb\">Acc</abbr></td> <td class=\"htt word\" data-word=\"iyattin\" data-language=\"ht\">iyattin</td> </tr>\n</table></p>",
