	"l\u016bli": "<p class=\"definition\" data-language=\"en\">Pool, lake, body of water</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\"><abbr title=\"Nominative: subject of a verb\">Nom</abbr></td> <td class=\"htt word\" data-word=\"l\u016bli\u0161\" data-language=\"ht\">l\u016bli\u0161</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Dative: location or destination\">Dat</abbr></td> <td class=\"htt word\" data-word=\"l\u016bliya\" data-language=\"ht\">l\u016bliya</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Accusative: object of a verb\">Acc</abbr></td> <td class=\"htt word\" data-word=\"l\u016blin\" data-language=\"ht\">l\u016blin</td> </tr>\n</table></p>",
